        inboxId: inboxId,
        threadId: threadId,
        emailId: emailId,
        to: to,
        idempotencyKey: idempotencyKey,
        cc: cc,
        bcc: bcc,
        html: html,
        text: text,
        subject: subject,
        attachments: attachments,
        headers: headers,
        requestOptions: requestOptions);
  }

  /// Lists unsent drafts in an inbox, ordered by most recently updated. Use `after` or `before` with a Draft ID from the current page to navigate results; do not supply both cursors together.
  ///
  /// Returns the unsent drafts on the inbox, most recently updated first. The `after` and `before` cursors take a Draft ID from the current page, and only one of them can be passed. A cursor that is not a UUID, or both cursors together, return a 422. A cursor that is not an unsent draft on this inbox returns a 404.
  Future<ListInboxDraftsResponseSuccess> listDrafts(
      {required String inboxId,
      SdkOptional<int> limit = const SdkOmitted(),
      SdkOptional<String> after = const SdkOmitted(),
      SdkOptional<String> before = const SdkOmitted(),
      RequestOptions? requestOptions}) async {
    return inboxes_methods.inboxesListDrafts(_config,
        inboxId: inboxId,
        limit: limit,
        after: after,
        before: before,
        requestOptions: requestOptions);
  }

  /// Creates an unsent draft in an inbox, either as a new thread or as a reply in an existing thread. Supply at least one non-empty recipient, subject, body, or attachment field; reply drafts require both `thread_id` and `reply_to_email_id`. If a reply draft already exists for the target email, the response returns its ID and only a supplied `attachments` value is applied.
  ///
  /// Creates an unsent draft on the inbox. Omit `thread_id` and `reply_to_email_id` for a draft that starts a new thread. Pass both together for a reply draft in an existing thread. A reply draft without `to` is addressed to the sender of the email it replies to, or to its Reply-To when set. For an email the inbox sent, it defaults to that email's `to` recipients. Send `to: []` to leave it empty. At least one of `to`, `cc`, `bcc`, `subject`, `text`, `html` or `attachments` must be non-empty. The combined recipients of `to`, `cc` and `bcc` cannot exceed 50. Attachments are stored on the draft, so each one needs `content`, `filename` and `content_type`. Returns 201 for a new draft. Only one unsent reply draft can target an email, so a reply draft request for an email that already has one returns 200 with the ID of the existing draft. An unknown `thread_id`, or a `reply_to_email_id` that is not in that thread, returns a 404. That request ignores every other field, except `attachments`, which replaces the attachments of the existing draft when sent. A reply draft created without `subject` stores an empty subject and gets no `Re:` prefix, so set one before you send it.
  Future<CreateInboxDraftResponseSuccess> createDraft(
      {required String inboxId,
      SdkOptional<String> idempotencyKey = const SdkOmitted(),
      SdkOptional<List<String>?> to = const SdkOmitted(),
      SdkOptional<List<String>?> cc = const SdkOmitted(),
      SdkOptional<List<String>?> bcc = const SdkOmitted(),
      SdkOptional<String?> subject = const SdkOmitted(),
      SdkOptional<String?> html = const SdkOmitted(),
      SdkOptional<String?> text = const SdkOmitted(),
      SdkOptional<List<InboxDraftAttachmentInput>?> attachments =
          const SdkOmitted(),
      SdkOptional<String> threadId = const SdkOmitted(),
      SdkOptional<String> replyToEmailId = const SdkOmitted(),
      RequestOptions? requestOptions}) async {
    return inboxes_methods.inboxesCreateDraft(_config,
        inboxId: inboxId,
        idempotencyKey: idempotencyKey,
        to: to,
        cc: cc,
        bcc: bcc,
        subject: subject,
        html: html,
        text: text,
        attachments: attachments,
        threadId: threadId,
        replyToEmailId: replyToEmailId,
        requestOptions: requestOptions);
  }

  /// Retrieves a specific draft from an inbox. Use the inbox and draft identifiers to inspect its recipients, content, thread association, timestamps, and stored attachments.
  Future<InboxDraft> getDraft(
      {required String inboxId,
      required String draftId,
      RequestOptions? requestOptions}) async {
    return inboxes_methods.inboxesGetDraft(_config,
        inboxId: inboxId, draftId: draftId, requestOptions: requestOptions);
  }

  /// Updates the content of an unsent draft in an inbox. Send only the fields you want to change; sending `attachments` replaces all attachments, while sending `text` or `html` replaces the entire body. The merged draft must retain at least one non-empty field and no more than 50 combined recipients.
  ///
  /// Updates the content of an unsent draft. Omitted fields are left unchanged. Send at least one of `to`, `cc`, `bcc`, `subject`, `text`, `html` or `attachments`. Sending `attachments` replaces every attachment on the draft. A request that sets `text` or `html` replaces the whole body. The body part you omit from that request becomes `null`. The merged draft must still contain at least one non-empty field, and its combined recipients cannot exceed 50. A draft that was already sent, or that changed during the request, returns a 409.
  Future<InboxDraft> updateDraft(
      {required String inboxId,
      required String draftId,
      SdkOptional<List<String>?> to = const SdkOmitted(),
      SdkOptional<List<String>?> cc = const SdkOmitted(),
      SdkOptional<List<String>?> bcc = const SdkOmitted(),
      SdkOptional<String?> subject = const SdkOmitted(),
      SdkOptional<String?> html = const SdkOmitted(),
      SdkOptional<String?> text = const SdkOmitted(),
      SdkOptional<List<InboxDraftAttachmentInput>?> attachments =
          const SdkOmitted(),
      RequestOptions? requestOptions}) async {
    return inboxes_methods.inboxesUpdateDraft(_config,
        inboxId: inboxId,
        draftId: draftId,
        to: to,
        cc: cc,
        bcc: bcc,
        subject: subject,
        html: html,
        text: text,
        attachments: attachments,
        requestOptions: requestOptions);
  }

  /// Deletes an unsent draft from an inbox. Use the inbox and draft identifiers to select the draft to discard; drafts that have already been sent are not eligible for removal.
  ///
  /// Discards an unsent draft. A draft that was already sent, or that changed during the request, returns a 409.
  Future<RemoveInboxDraftResponseSuccess> removeDraft(
      {required String inboxId,
      required String draftId,
      RequestOptions? requestOptions}) async {
    return inboxes_methods.inboxesRemoveDraft(_config,
        inboxId: inboxId, draftId: draftId, requestOptions: requestOptions);
  }

  /// Submits an unsent draft from the inbox address. A reply draft is sent in its existing thread, while a standalone draft starts a new thread; you can add custom headers in the optional request body. Before sending, the draft must have at least one recipient, a non-empty subject, and an HTML or plain-text body.
  ///
  /// Sends the draft from the inbox address. A reply draft is sent in its thread. A draft without a thread starts a new thread. The draft must have at least one `to` recipient, a non-empty `subject`, and `html` or `text`, or the request returns a 422. A draft that was already sent returns a 409. The request body is optional and takes only `headers`. The whole email, encoded, can be at most 40 MB, or the request returns a 422.
  Future<SendInboxDraftResponseSuccess> sendDraft(
      {required String inboxId,
      required String draftId,
      SdkOptional<String> idempotencyKey = const SdkOmitted(),
      SdkOptional<Map<String, String>?> headers = const SdkOmitted(),
      RequestOptions? requestOptions}) async {
    return inboxes_methods.inboxesSendDraft(_config,
        inboxId: inboxId,
        draftId: draftId,
        idempotencyKey: idempotencyKey,
        headers: headers,
        requestOptions: requestOptions);
  }
}

class Resend {
  final ClientConfig _config;
  late final EmailsNamespace emails;
  late final ReceivingEmailsNamespace receivingEmails;
  late final DomainsNamespace domains;
  late final ApiKeysNamespace apiKeys;
  late final OauthNamespace oauth;
  late final TemplatesNamespace templates;
  late final AudiencesNamespace audiences;
  late final ContactsNamespace contacts;
  late final BroadcastsNamespace broadcasts;
  late final WebhooksNamespace webhooks;
  late final SegmentsNamespace segments;
  late final TopicsNamespace topics;
  late final ContactPropertiesNamespace contactProperties;
  late final LogsNamespace logs;
  late final AutomationsNamespace automations;
  late final EventsNamespace events;
  late final SuppressionsNamespace suppressions;
  late final UsageNamespace usage;
  late final InboxesNamespace inboxes;
  Resend(ClientConfig config) : _config = config {
    emails = EmailsNamespace(config);
    receivingEmails = ReceivingEmailsNamespace(config);
    domains = DomainsNamespace(config);
    apiKeys = ApiKeysNamespace(config);
    oauth = OauthNamespace(config);
    templates = TemplatesNamespace(config);
    audiences = AudiencesNamespace(config);
    contacts = ContactsNamespace(config);
    broadcasts = BroadcastsNamespace(config);
    webhooks = WebhooksNamespace(config);
    segments = SegmentsNamespace(config);
    topics = TopicsNamespace(config);
    contactProperties = ContactPropertiesNamespace(config);
    logs = LogsNamespace(config);
    automations = AutomationsNamespace(config);
    events = EventsNamespace(config);
    suppressions = SuppressionsNamespace(config);
    usage = UsageNamespace(config);
    inboxes = InboxesNamespace(config);
  }

  /// Turns SDK logging on and configures it. Logging is OFF by default — this
  /// SDK reports nothing until you call this (or construct the client with a
  /// [ClientConfig] whose logging is enabled). Reports go to the endpoint this
  /// build was generated with, or to the `endpoint` you pass; with neither,
  /// nothing is sent. Pass `enabled: false` to turn logging back off.
  LoggingConfig setLoggingConfig({
    bool? enabled,
    String? endpoint,
    String? apiKey,
    String? environment,
    String? release,
    Map<String, dynamic>? user,
    Map<String, dynamic>? tags,
    bool? filterPii,
  }) {
    final logging = _config.logging ??= LoggingConfig();
    if (endpoint != null) logging.endpoint = endpoint;
    if (apiKey != null) logging.apiKey = apiKey;
    if (environment != null) logging.environment = environment;
    if (release != null) logging.release = release;
    if (user != null) logging.user = user;
    if (tags != null) logging.tags = tags;
    if (filterPii != null) logging.filterPii = filterPii;
    logging.enabled = enabled ?? true;
    return logging;
  }
}
